["def calculator(num1, num2, operator):
    """
    Perform a calculation based on the given operator.

    :param num1: First number, can be int or float
    :param num2: Second number, can be int or float
    :param operator: Operator, one of '+', '-', '*', '/'
    :return: Result of the calculation
    """
    if operator == '+':
        return num1 + num2
    elif operator == '-':
        return num1 - num2
    elif operator == '*':
        return num1 * num2
    elif operator == '/':
        if num2 == 0:
            return "Error: Division by zero"
        return num1 / num2
    else:
        return "Error: Invalid operator""]

