class LinearClassifier:
    def __init__(self, learning_rate=0.01, regularization_strength=0.01, epochs=1000):
        self.learning_rate = learning_rate
        self.regularization_strength = regularization_strength
        self.epochs = epochs
        self.weights = None
        self.bias = None

    def fit(self, X, y):
        num_samples, num_features = X.shape
        self.weights = np.zeros(num_features)
        self.bias = 0

        for epoch in range(self.epochs):
            for idx, x_i in enumerate(X):
                condition = y[idx] * (np.dot(x_i, self.weights) - self.bias) >= 1
                if condition:
                    self.weights -= self.learning_rate * (2 * self.regularization_strength * self.weights)
                else:
                    self.weights -= self.learning_rate * (2 * self.regularization_strength * self.weights - np.dot(x_i, y[idx]))
                    self.bias -= self.learning_rate * y[idx]

    def predict(self, X):
        linear_output = np.dot(X, self.weights) - self.bias
        return np.sign(linear_output)"]

