["import random
from typing import Tuple
from sympy import isprime, mod_inverse

def generate_prime(bits, seed=None):
    if seed:
        random.seed(seed)
    while True:
        p = random.getrandbits(bits)
        if isprime(p):
            return p

def generate_key(k: int, seed: int = None) -> Tuple[int, int, int]:
    if k < 16:
        raise ValueError("k must be at least 16 bits.")

    bits = k // 2
    p = generate_prime(bits, seed)
    q = generate_prime(bits, seed)

    n = p * q
    phi = (p - 1) * (q - 1)

    e = 65537  # A common choice for e
    d = mod_inverse(e, phi)

    return n, e, d

def encrypt(data: int, e: int, n: int) -> int:
    if data >= n:
        raise ValueError("Data must be less than n.")
    return pow(data, e, n)

def decrypt(data: int, d: int, n: int) -> int:
    return pow(data, d, n)"]

