["def longest_path_length(n, edges):
    from collections import defaultdict, deque

    if n == 1:
        return 0

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def bfs(start_node):
        visited = [-1] * (n + 1)
        queue = deque([start_node])
        visited[start_node] = 0
        farthest_node = start_node

        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if visited[neighbor] == -1:
                    queue.append(neighbor)
                    visited[neighbor] = visited[node] + 1
                    if visited[neighbor] > visited[farthest_node]:
                        farthest_node = neighbor

        return farthest_node, visited[farthest_node]

    start, _ = bfs(1)
    end, distance = bfs(start)

    return distance

def solve(input_lines):
    input_iter = iter(input_lines)
    result = []

    while True:
        n = int(next(input_iter).strip())
        if n == 0:
            break
        edges = []
        for _ in range(n - 1):
            u, v = map(int, next(input_iter).strip().split())
            edges.append((u, v))
        result.append(longest_path_length(n, edges))

    return result"]

