["class CustomIterator:
    def __init__(self, data):
        if not isinstance(data, list) or not all(isinstance(i, int) for i in data):
            raise ValueError("CustomIterator requires a list of integers.")
        self.data = data
        self.index = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.index >= len(self.data):
            raise StopIteration
        result = self.data[self.index]
        self.index += 1
        return result

    def send(self, value):
        if not isinstance(value, int):
            raise ValueError("Value to send must be an integer.")
        if self.index >= len(self.data):
            raise StopIteration
        # For simplicity in this example, let's assume we just add the value to the current element.
        result = self.data[self.index] + value
        self.index += 1
        return result"]

