def find_min_time_difference(times: List[str]) -> int:
    if len(times) < 2:
        return 0

    def time_to_minutes(t: str) -> int:
        h, m = map(int, t.split(':'))
        return h * 60 + m

    minutes = sorted(time_to_minutes(t) for t in times)
    minutes.append(minutes[0] + 24 * 60)  # Account for the wrap-around scenario

    min_diff = float('inf')
    for i in range(1, len(minutes)):
        min_diff = min(min_diff, minutes[i] - minutes[i-1])

    return min_diff"]

