from typing import Dict, List, Tuple

def enhanced_prims_minimum_spanning(graph: Dict[str, List[Tuple[int, str]]]) -> Tuple[int, List[Tuple[str, str, int]]]:
    if not graph:
        return 0, []

    # Initialize
    start_node = next(iter(graph))
    min_heap = [(0, start_node, None)]  # (cost, to_node, from_node)
    total_cost = 0
    mst_edges = []
    visited = set()

    while min_heap:
        cost, to_node, from_node = heapq.heappop(min_heap)

        if to_node in visited:
            continue

        visited.add(to_node)
        if from_node:
            mst_edges.append((from_node, to_node, cost))

        total_cost += cost

        for edge_cost, neighbor in graph[to_node]:
            if neighbor not in visited:
                heapq.heappush(min_heap, (edge_cost, neighbor, to_node))

    # Check if all nodes are connected
    if len(visited) != len(graph):
        return "The graph is disconnected", []

    return total_cost, mst_edges"]

