["from typing import List
import heapq

def trap_rain_water(heights: List[List[int]]) -> int:
    if not heights or not heights[0]:
        return 0

    m, n = len(heights), len(heights[0])
    visited = [[False] * n for _ in range(m)]
    min_heap = []

    # Push all the boundary cells into the heap
    for i in range(m):
        for j in (0, n-1):
            heapq.heappush(min_heap, (heights[i][j], i, j))
            visited[i][j] = True
    for j in range(n):
        for i in (0, m-1):
            heapq.heappush(min_heap, (heights[i][j], i, j))
            visited[i][j] = True

    total_water = 0
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while min_heap:
        height, x, y = heapq.heappop(min_heap)
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                trapped_water = max(0, height - heights[nx][ny])
                total_water += trapped_water
                heapq.heappush(min_heap, (max(height, heights[nx][ny]), nx, ny))

    return total_water"]

