class TodoList:
    def __init__(self):
        self.todo_lists = defaultdict(list)

    def add_task(self, list_name, task_description):
        # Check if task already exists in the list
        for task in self.todo_lists[list_name]:
            if task['task'] == task_description:
                return  # Task already exists, do nothing
        self.todo_lists[list_name].append({"task": task_description, "completed": False})

    def remove_task(self, list_name, task_description):
        self.todo_lists[list_name] = [task for task in self.todo_lists[list_name] if task['task'] != task_description]

    def mark_completed(self, list_name, task_description):
        for task in self.todo_lists[list_name]:
            if task['task'] == task_description:
                task['completed'] = True

    def get_tasks(self, list_name):
        return self.todo_lists[list_name]"]

["class LanternLightShow:
    def __init__(self, n, arr, mod):
        self.n = n
        self.arr = arr
        self.mod = mod
        self.prefix_sums = [0] * (n + 1)
        self.calculate_prefix_sums()

    def calculate_prefix_sums(self):
        for i in range(1, self.n + 1):
            self.prefix_sums[i] = (self.prefix_sums[i - 1] + self.arr[i - 1]) % self.mod

    def update(self, index, value):
        self.arr[index - 1] = value
        self.calculate_prefix_sums()

    def query_sum(self, l, r):
        return (self.prefix_sums[r] - self.prefix_sums[l - 1]) % self.mod

def process_queries(n, q, mod, arr, queries):
    light_show = LanternLightShow(n, arr, mod)
    results = []

    for query in queries:
        if query[0] == 1:
            # Update operation: 1 p x
            _, p, x = query
            light_show.update(p, x)
        elif query[0] == 2:
            # Sum query: 2 l r
            _, l, r = query
            results.append(light_show.query_sum(l, r))

    return results"]

