def generate_random_matrix(rows, cols):
    return [[round(random.uniform(0, 1), 2) for _ in range(cols)] for _ in range(rows)]

def check_commutative(mat1, mat2, operation):
    result1 = operation.add(mat1, mat2)
    result2 = operation.add(mat2, mat1)
    return result1 == result2

def check_associative(mat1, mat2, mat3, operation):
