["class FenwickTree:
    def __init__(self, size):
        self.size = size
        self.tree = [0] * (size + 1)

    def update(self, index, delta):
        while index <= self.size:
            self.tree[index] += delta
            index += index & -index

    def query(self, index):
        sum_ = 0
        while index > 0:
            sum_ += self.tree[index]
            index -= index & -index
        return sum_

def process_operations(N, Q, sequence, operations):
    fenwick_tree = FenwickTree(N)
    for idx, value in enumerate(sequence):
        fenwick_tree.update(idx + 1, value)

    result = []
    for operation in operations:
        if operation[0] == 1:
            index, new_value = operation[1], operation[2]
            current_value = sequence[index - 1]
            delta = new_value - current_value
            sequence[index - 1] = new_value
            fenwick_tree.update(index, delta)
        elif operation[0] == 2:
            l, r = operation[1], operation[2]
            sum_of_range = fenwick_tree.query(r) - fenwick_tree.query(l - 1)
            result.append(sum_of_range)
    return result"]

