["import random

class StockMarketGame:
    def __init__(self, starting_funds=1000, total_days=50):
        self.funds = starting_funds
        self.total_days = total_days
        self.current_day = 0
        self.shares_owned = 0
        self.stock_price = 100

    def simulate_stock_price(self):
        self.stock_price = max(1, self.stock_price + random.randint(-10, 10))

    def buy_shares(self, amount):
        shares_to_buy = min(amount // self.stock_price, self.funds // self.stock_price)
        cost = shares_to_buy * self.stock_price
        self.funds -= cost
        self.shares_owned += shares_to_buy

    def sell_shares(self, amount):
        shares_to_sell = min(amount, self.shares_owned)
        revenue = shares_to_sell * self.stock_price
        self.funds += revenue
        self.shares_owned -= shares_to_sell

    def next_day(self):
        self.simulate_stock_price()
        self.current_day += 1

    def game_status(self):
        return {
            'day': self.current_day,
            'funds': self.funds,
            'shares_owned': self.shares_owned,
            'stock_price': self.stock_price
        }

    def is_game_over(self):
        return self.current_day >= self.total_days or self.funds <= 0

def simulate_game(actions):
    game = StockMarketGame()
    results = []

    for action in actions:
        if game.is_game_over():
            break

        if action['type'] == 'buy':
            game.buy_shares(action['amount'])
        elif action['type'] == 'sell':
            game.sell_shares(action['amount'])

        game.next_day()
        results.append(game.game_status())

    return results"]

