from typing import List, Dict, Set

class Graph:
    def __init__(self):
        self.adjacency_list: Dict[int, Set[int]] = collections.defaultdict(set)

    def add_node(self, node: int) -> None:
        self.adjacency_list[node]

    def add_edge(self, node1: int, node2: int) -> None:
        self.adjacency_list[node1].add(node2)
        self.adjacency_list[node2].add(node1)

    def get_adjacent_nodes(self, node: int) -> Set[int]:
        return self.adjacency_list[node]

    def find_shortest_path(self, start: int, end: int) -> List[int]:
        if start == end:
            return [start]

        queue = collections.deque([(start, [start])])
        visited = set()

        while queue:
            current_node, path = queue.popleft()

            if current_node in visited:
                continue

            visited.add(current_node)

            for neighbor in self.get_adjacent_nodes(current_node):
                if neighbor == end:
                    return path + [end]
                if neighbor not in visited:
                    queue.append((neighbor, path + [neighbor]))

        return []  # if no path found"]

