from stat import *
from typing import List, Dict, Any
import stat

def analyze_directory(directory: str) -> List[Dict[str, Any]]:
    def walktree(top, result):
        for f in os.listdir(top):
            pathname = os.path.join(top, f)

            try:
                st = os.lstat(pathname)
                mode = st.st_mode
            except FileNotFoundError:
                continue

            entry = {'path': pathname}

            if S_ISDIR(mode):
                entry['type'] = 'directory'
                entry['size'] = None
            elif S_ISREG(mode):
                entry['type'] = 'file'
                entry['size'] = st.st_size
            elif S_ISCHR(mode):
                entry['type'] = 'character device'
                entry['size'] = None
            elif S_ISBLK(mode):
                entry['type'] = 'block device'
                entry['size'] = None
            elif S_ISFIFO(mode):
                entry['type'] = 'fifo'
                entry['size'] = None
            elif S_ISLNK(mode):
                entry['type'] = 'symlink'
                entry['size'] = None
            elif S_ISSOCK(mode):
                entry['type'] = 'socket'
                entry['size'] = None
            else:
                entry['type'] = 'unknown'
                entry['size'] = None

            entry['permissions'] = stat.filemode(mode)

            result.append(entry)

            if S_ISDIR(mode):
                walktree(pathname, result)

    result = []
    walktree(directory, result)
    return result"]

