    def __init__(self):
        self.seq = []
        self.prefix_sums = [0]  # maintains prefix sums for optimization

    def append(self, x):
        self.seq.append(x)
        self.prefix_sums.append(self.prefix_sums[-1] + x)

    def prefix_sum(self, k):
        return self.prefix_sums[k]

    def remove_last(self):
        if self.seq:
            self.seq.pop()
            self.prefix_sums.pop()

    def get(self, i):
