def process_queries(n, queries):
    sequence = Sequence()
    result = []

    for query in queries:
        parts = query.split()
        command = int(parts[0])

        if command == 0:
            x = int(parts[1])
            sequence.append(x)
        elif command == 1:
            k = int(parts[1])
            result.append(sequence.prefix_sum(k))
        elif command == 2:
