["def bellman_ford_with_path(graph, source, destination):
    """
    Determines the shortest path from source to destination in the given graph.

    :param graph: dict, a dictionary where keys are nodes and values are dictionaries
                  with keys as adjacent nodes and values as edge weights.
    :param source: str, the source node.
    :param destination: str, the destination node.
    :return: tuple, (bool, list) where the boolean indicates the presence of a negative cycle
             (True if no negative cycle, False if negative cycle exists). The list contains
             the shortest path from source to destination if no negative cycle exists, 
             otherwise it is empty.
    """
    # Initialize distances and predecessors
    distance = {node: float('inf') for node in graph}
    predecessor = {node: None for node in graph}

    distance[source] = 0

    # Relax edges repeatedly (|V| - 1 times)
    for _ in range(len(graph) - 1):
        for u in graph:
            for v in graph[u]:
                if distance[u] + graph[u][v] < distance[v]:
                    distance[v] = distance[u] + graph[u][v]
                    predecessor[v] = u

    # Check for negative-weight cycles
    for u in graph:
        for v in graph[u]:
            if distance[u] + graph[u][v] < distance[v]:
                return (False, [])  # Negative-weight cycle detected

    # Reconstruct the shortest path from source to destination
    path = []
    current = destination
    while current is not None:
        path.append(current)
        current = predecessor[current]
    path.reverse()

    if path[0] == source:
        return (True, path)

    return (True, [])"]

