["def min_moves_to_return(S):
    """
    Returns the minimum number of moves required for the robot to return
    to the original position (0,0), or -1 if it is not possible.
    """
    x, y = 0, 0

    for move in S:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1

    if x == 0 and y == 0:
        return len(S)
    else:
        return -1"]

