["def min_awards(n, scores):
    """
    Returns the minimum number of awards needed based on the scores of n participants.
    """
    if n == 0:
        return 0

    awards = [1] * n  # start by giving each participant 1 award

    # Traverse from left to right
    for i in range(1, n):
        if scores[i] > scores[i-1]:
            awards[i] = awards[i-1] + 1

    # Traverse from right to left
    for i in range(n-2, -1, -1):
        if scores[i] > scores[i+1]:
            awards[i] = max(awards[i], awards[i+1] + 1)

    return sum(awards)"]

