["def is_right_angled_triangle(x1, y1, x2, y2, x3, y3):
    def squared_distance(x1, y1, x2, y2):
        return (x1 - x2) ** 2 + (y1 - y2) ** 2

    # Squared lengths of the sides of the triangle
    d1 = squared_distance(x1, y1, x2, y2)
    d2 = squared_distance(x2, y2, x3, y3)
    d3 = squared_distance(x3, y3, x1, y1)

    # Check the Pythagorean theorem for right-angled triangle
    return (d1 + d2 == d3) or (d1 + d3 == d2) or (d2 + d3 == d1)

def solve(t, test_cases):
    results = []
    for case in test_cases:
        x1, y1, x2, y2, x3, y3 = case
        if is_right_angled_triangle(x1, y1, x2, y2, x3, y3):
            results.append("YES")
        else:
            results.append("NO")
    return results

