import time

class CustomTelnetClient:
    def __init__(self, host, port, timeout=10):
        self.host = host
        self.port = port
        self.timeout = timeout
        self.connection = None

    def connect(self):
        if self.connection is None:
            self.connection = telnetlib.Telnet(self.host, self.port, self.timeout)
        else:
            raise Exception("Connection already established")

    def close(self):
        if self.connection:
            self.connection.close()
            self.connection = None

    def execute_command(self, command):
        if self.connection is None:
            raise Exception("Not connected to any server")
        self.connection.write(command.encode('ascii') + b"\n")
        return self.connection.read_until(b"\n", self.timeout).decode('ascii')

    def set_option_negotiation_callback(self, callback):
        if self.connection:
            self.connection.set_option_negotiation_callback(callback)
        else:
            raise Exception("Not connected to any server")

    def __enter__(self):
        self.connect()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()

    def interactive_mode(self):
        print("Entering interactive mode. Press Ctrl+C to exit.")
        try:
            while True:
                command = input(">>> ")
                response = self.execute_command(command)
                print(response)
        except KeyboardInterrupt:
            print("\nExiting interactive mode.")"]

