["def cycle_sort(arr):
    n = len(arr)

    # Traverse array elements and put them on the correct index
    for start in range(0, n - 1):
        item = arr[start]

        # Find the position where we put the element
        pos = start
        for i in range(start + 1, n):
            if arr[i] < item:
                pos += 1

        # If the item is already in the correct position
        if pos == start:
            continue

        # Skip duplicates
        while item == arr[pos]:
            pos += 1

        # Put the item to it's right position
        arr[pos], item = item, arr[pos]

        # Rotate rest of the cycle
        while pos != start:
            pos = start
            for i in range(start + 1, n):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1

            arr[pos], item = item, arr[pos]

    return arr"]

