["from typing import List

class Item:
    def __init__(self, value, weight):
        self.value = value
        self.weight = weight

def get_maximum_value(items: List[Item], capacity: int) -> int:
    # Initialize a list to keep track of the maximum value at each capacity
    dp = [0] * (capacity + 1)

    # Iterate through each item
    for item in items:
        # Iterate through all capacities from highest to lowest
        for w in range(capacity, item.weight - 1, -1):
            # Update the dp list if the current item is included
            dp[w] = max(dp[w], dp[w - item.weight] + item.value)

    return dp[capacity]"]

["def find(parent, i):
    if parent[i] == i:
        return i
    else:
        parent[i] = find(parent, parent[i])
        return parent[i]

def union(parent, rank, x, y):
    root_x = find(parent, x)
    root_y = find(parent, y)

    if root_x != root_y:
        if rank[root_x] > rank[root_y]:
            parent[root_y] = root_x
        elif rank[root_x] < rank[root_y]:
            parent[root_x] = root_y
        else:
            parent[root_y] = root_x
            rank[root_x] += 1

def min_construction_cost(n, m, roads):
    edges = []
    for road in roads:
        u, v, w, c = road
        edges.append((c, u, v))

    edges.sort()

    parent = [i for i in range(n + 1)]
    rank = [0] * (n + 1)

    total_cost = 0
    num_edges = 0

    for edge in edges:
        cost, u, v = edge
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            total_cost += cost
            num_edges += 1
            if num_edges == n - 1:
                break

    return total_cost"]

