        return 0
    return root.val + tree_sum(root.left) + tree_sum(root.right)

def tree_height(root):
    if not root:
        return 0
    return max(tree_height(root.left), tree_height(root.right)) + 1

def tree_max_value(root):
    if not root:
        return float('-inf')
    return max(root.val, tree_max_value(root.left), tree_max_value(root.right))

